-- Generated by tools/GenerateRptViews.py; edit the generator, not this file.
-- One row per invoice line, for revenue by project, task or line type. Needs invoice.view.
CREATE VIEW rpt.InvoiceLine
AS
SELECT
    ie.Id AS InvoiceLineId,
    ie.InvoiceId AS InvoiceId,
    i.InvoiceNumber AS InvoiceNumber,
    i.InvoiceDate AS InvoiceDate,
    s.SystemCode AS InvoiceStatusCode,
    i.ClientId AS ClientId,
    c.Name AS ClientName,
    ie.ProjectId AS ProjectId,
    p.Name AS ProjectName,
    t.TaskKey AS TaskKey,
    lt.Name AS LineType,
    lt.SystemCode AS LineTypeCode,
    ie.Description AS Description,
    ie.Amount AS Amount,
    ie.ServicePeriodStart AS ServicePeriodStart,
    ie.ServicePeriodEnd AS ServicePeriodEnd
FROM ar.InvoiceEntry AS ie
JOIN ar.Invoice AS i ON i.TenantId = ie.TenantId AND i.Id = ie.InvoiceId
JOIN crm.Client AS c ON c.TenantId = i.TenantId AND c.Id = i.ClientId
JOIN lkp.InvoiceStatus AS s ON s.TenantId = i.TenantId AND s.Id = i.InvoiceStatusId
JOIN lkp.InvoiceLineType AS lt ON lt.TenantId = ie.TenantId AND lt.Id = ie.LineTypeId
LEFT JOIN crm.ClientProject AS p ON p.TenantId = ie.TenantId AND p.Id = ie.ProjectId
LEFT JOIN crm.ClientTask AS t ON t.TenantId = ie.TenantId AND t.Id = ie.TaskId
WHERE EXISTS (SELECT 1 FROM sec.fn_UserHasPermission(ie.TenantId, CONVERT(INT, SESSION_CONTEXT(N'UserId')), 'invoice.view'));
GO
